    "translation": [
      "Tanaka juga mungkin akan datang. Soal ini mungkin sulit. Teman saya mengatakan film itu menarik.",
      "Ibu mengatakan bahwa hari ini akan pulang terlambat. Saya pikir besok akan hujan.",
      "Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Pada pagi hari, jadwal hari itu diperiksa terlebih dahulu. Kegiatan pagi dan sore sedikit berbeda. Waktu penting ditulis dalam catatan. Pada hari dengan banyak rencana, urutannya ditentukan.",
      "Pada akhirnya, jadwal hari berikutnya juga diperiksa. Ada rencana untuk hari berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan."
    ],
