    "translation": [
      "Besok mungkin libur. Cerita itu mungkin tidak benar. Teman saya mengatakan film itu menarik.",
      "Ibu mengatakan bahwa hari ini akan pulang terlambat. Saya pikir besok akan hujan. Menurut saya buku ini menarik.",
      "Pada hari bercuaca baik, berjalan-jalan di taman. Hobi baru juga dimulai sedikit demi sedikit. Ada rencana untuk waktu luang berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya.",
      "Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai."
    ],
