    "translation": [
      "Saya pikir Tanaka tidak akan datang. Menurut saya cara itu yang paling baik. Yamada mengatakan akan pulang ke negaranya minggu depan. Teman saya mengatakan film itu menarik.",
      "Akhir pekan mungkin akan banyak orang. Tanaka juga mungkin akan datang. Saya pikir besok akan hujan.",
      "Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan.",
      "Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Pada pagi hari, jadwal hari itu diperiksa terlebih dahulu. Kegiatan pagi dan sore sedikit berbeda."
    ],
