    "translation": [
      "Saya membaca buku yang dibeli kemarin. Saya akan menunjukkan foto yang diambil di Jepang. Saya bekerja di perusahaan Jepang. Saya membelinya di toko dekat stasiun.",
      "Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang.",
      "Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Pada hari libur, waktu untuk hobi disediakan. Bersama teman, membicarakan film dan musik."
    ],
