    "translation": [
      "Saya sedang mencari hotel murah. Saya ingin tinggal di kota yang tenang. Orang yang saya temui di stasiun adalah Tanaka. Masakan yang dibuat ibu enak.",
      "Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Waktu keberangkatan dan jadwal kereta diperiksa. Di stasiun, peta dan petunjuk dilihat. Lokasi yang tidak dipahami ditanyakan kepada petugas stasiun.",
      "Barang bawaan dibuat sesedikit mungkin. Di tengah perjalanan, waktu diperiksa sekali lagi. Ada rencana untuk perjalanan berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan."
    ],
