    "translation": [
      "Saya bekerja di perusahaan Jepang. Saya bertemu guru yang terkenal. Saya akan menunjukkan foto yang diambil di Jepang.",
      "Saya membaca buku yang dibeli kemarin. Gunung yang bernama Fuji terkenal di Jepang.",
      "Bersama teman, membicarakan film dan musik. Ada juga hari ketika membaca buku di rumah. Pada hari bercuaca baik, berjalan-jalan di taman. Hobi baru juga dimulai sedikit demi sedikit. Ada rencana untuk waktu luang berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya.",
      "Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut."
    ],
