    "translation": [
      "Orang yang saya temui di stasiun adalah Tanaka. Kamus yang saya gunakan setiap hari adalah ini. Saya bertemu guru yang terkenal. Saya bekerja di perusahaan Jepang.",
      "Apakah Anda mengenal orang yang bernama Tanaka? Saya ingin tinggal di kota yang tenang. Saya mempelajari kata yang disebut 'mottainai'.",
      "Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang.",
      "Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Waktu keberangkatan dan jadwal kereta diperiksa. Di stasiun, peta dan petunjuk dilihat. Lokasi yang tidak dipahami ditanyakan kepada petugas stasiun. Barang bawaan dibuat sesedikit mungkin. Di tengah perjalanan, waktu diperiksa sekali lagi. Ada rencana untuk perjalanan berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya."
    ],
