    "translation": [
      "Saya membantu mengajari PR kepada adik perempuan. Saya menunjukkan jalan ke stasiun untuk teman. Teman membantu mengerjakan PR saya. Guru mengajarkan Kanji kepada saya.",
      "Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali.",
      "Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Pada pagi hari waktu pelajaran diperiksa. Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru. Kosakata yang belum dipahami ditulis di buku catatan."
    ],
