    "translation": [
      "Saya meminta/menerima bantuan guru untuk memperbaiki karangan. Saya dibuatkan masakan oleh ibu. Guru berkenan meminjamkan buku kepada saya. Guru berkenan menuliskan surat rekomendasi untuk saya.",
      "Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan. Pada pagi hari waktu pelajaran diperiksa. Di kelas, siswa membaca bahasa Jepang dan mendengarkan penjelasan guru. Kosakata yang belum dipahami ditulis di buku catatan. Saat istirahat, siswa membicarakan isi pelajaran bersama teman.",
      "Setelah pulang, isi pelajaran hari itu diperiksa sekali lagi. Ada rencana belajar berikutnya yang akan dilakukan. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan."
    ],
