    "translation": [
      "Guru berkenan menuliskan surat rekomendasi untuk saya. Guru berkenan meminjamkan buku kepada saya. Saya meminta/menerima bantuan guru untuk memperbaiki karangan.",
      "Saya mendapat bantuan rekan kerja untuk pekerjaan. Guru mengajarkan Kanji kepada saya. Saya membantu mengajari PR kepada adik perempuan.",
      "Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya. Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Beberapa informasi diperiksa dari pagi hingga siang.",
      "Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali."
    ],
