    "translation": [
      "Saya mengambilkan foto untuk teman. Saya membantu mengajari PR kepada adik perempuan. Saya diajari pengucapan oleh teman Jepang. Saya mendapat bantuan rekan kerja untuk pekerjaan.",
      "Saya menunjukkan jalan ke stasiun untuk teman. Saya membacakan buku untuk anak. Saya membawakan barang adik laki-laki.",
      "Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai. Dibanding pengalaman sebelumnya, kali ini penulis dapat bertindak sedikit lebih tenang. Pada akhirnya, kejadian hari itu dipikirkan kembali. Penulis berpendapat bahwa persiapan lebih awal membuat keadaan lebih tenang. Penting untuk tidak hanya melihat satu informasi, tetapi juga mempertimbangkan keseluruhan.",
      "Pada hari libur, waktu untuk hobi disediakan. Bersama teman, membicarakan film dan musik. Ada juga hari ketika membaca buku di rumah. Pada hari bercuaca baik, berjalan-jalan di taman. Hobi baru juga dimulai sedikit demi sedikit. Ada rencana untuk waktu luang berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya."
    ],
