    "translation": [
      "Setelah tiba di stasiun, saya akan menghubungi Anda. Kalau pekerjaan sudah selesai, tolong telepon. Kalau menuju stasiun, bus ini praktis. Kalau masakan sederhana, saya bisa membuatnya.",
      "Kalau ada waktu, saya akan menonton film. Kalau hujan, saya tidak akan keluar. Kalau pergi ke Jepang, saya ingin melihat Kyoto.",
      "Walaupun rencana berubah di perjalanan, waktunya diperiksa lagi. Ada rencana untuk perjalanan berikutnya. Karena ada kendala tersebut, dilakukan langkah yang sesuai untuk mengatasinya. Penulis menyatakan keinginan yang berkaitan dengan topik bacaan. Setelah memastikan waktu, kegiatan utama dilakukan. Penulis menghubungkan situasi sekarang dengan pengalaman sebelumnya. Walaupun ada kesulitan, penulis tetap melakukan langkah untuk mengatasinya.",
      "Penulis menyampaikan pendapat berdasarkan pengalaman tersebut. Saat pergi ke tempat tersebut, penulis memeriksa waktu dan tempat. Jika jadwal berubah, penulis akan menghubungi temannya lebih awal. Beberapa informasi diperiksa dari pagi hingga siang. Keputusan dibuat dengan membandingkan dua rencana, bukan hanya satu. Pertama hal yang diperlukan diperiksa, lalu kegiatan dilakukan secara berurutan. Ada sedikit masalah di tengah kegiatan, tetapi kegiatan dilanjutkan sampai selesai."
    ],
